import pyotp
import pytest

from app.auth import AuthError, get_session, login, otp_header
from app.config import USERS


def otp_de(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", otp_de("alice"))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", otp_de("alice"))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", otp_de("alice"))


def test_login_otp_incorrecto_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_acepta_cualquier_codigo_si_se_sustituye_verificar_otp(monkeypatch):
    monkeypatch.setattr("app.auth.verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "lo-que-sea")
    assert s.username == "alice"


def test_otp_header_lee_x_otp():
    assert otp_header("123456") == "123456"
    assert otp_header() == ""


def test_endpoint_login(client):
    assert client.post(
        "/login",
        json={"username": "bob", "password": "bob-pass", "otp": otp_de("bob")},
    ).status_code == 200
    assert client.post(
        "/login",
        json={"username": "bob", "password": "x", "otp": otp_de("bob")},
    ).status_code == 401


def test_endpoint_login_sin_otp_o_con_otp_invalido(client):
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401
    assert client.post(
        "/login",
        json={"username": "bob", "password": "bob-pass", "otp": "000000"},
    ).status_code == 401

